<script setup lang="ts">
import {computed,onBeforeUnmount,ref} from 'vue';
import AppDialog from './AppDialog.vue';
import {collectionQueryIssue,type CollectionQuery as Query} from '../monitoring';
const props=defineProps<{request:<T>(path:string,method?:string,body?:unknown,signal?:AbortSignal)=>Promise<T>}>();
const emit=defineEmits<{created:[id:number]}>();
const open=ref(false),loading=ref(false),busy=ref(false),error=ref(''),rows=ref<Query[]>([]),selection=ref(0),confirmed=ref(false);
const chosen=computed(()=>rows.value.find(row=>row.id===selection.value));
const issue=computed(()=>collectionQueryIssue(chosen.value));
const eligible=computed(()=>!issue.value);
let alive=true,generation=0,controller:AbortController|undefined;
async function load(){const current=++generation;controller?.abort();controller=new AbortController();loading.value=true;error.value='';rows.value=[];selection.value=0;confirmed.value=false;try{const result=await props.request<Query[]>('/api/contexto/monitoramentos','GET',undefined,controller.signal);if(alive&&current===generation)rows.value=result;}catch(cause){if(alive&&current===generation)error.value=(cause as Error).message;}finally{if(alive&&current===generation)loading.value=false;}}
function show(){open.value=true;void load();}
function close(){if(busy.value)return;open.value=false;generation++;controller?.abort();}
async function submit(){if(busy.value||loading.value||!confirmed.value||!eligible.value)return;const current=generation;busy.value=true;error.value='';try{const result=await props.request<{id:number;status:string}>('/api/contexto/execucoes','POST',{monitoramento_id:selection.value});if(alive&&current===generation){open.value=false;emit('created',result.id);}}catch(cause){if(alive&&current===generation)error.value=(cause as Error).message;}finally{if(alive&&current===generation)busy.value=false;}}
onBeforeUnmount(()=>{alive=false;generation++;controller?.abort();});
</script>
<template><button type="button" class="primary" @click="show">Solicitar coleta</button>
<AppDialog v-if="open" title="Solicitar coleta" :busy="busy" @close="close"><p>Selecione uma consulta deste escritório e confira seus filtros antes de solicitar a execução. O processamento depende do worker e dos limites configurados. Serão usados os filtros vigentes no início do processamento.</p><p v-if="loading" role="status">Carregando consultas…</p><p v-if="error" role="alert">{{ error }}</p><button v-if="!busy" type="button" class="secondary" :disabled="loading" @click="load">Atualizar consultas</button><form class="vue-form" @submit.prevent="submit"><label>Consulta para coleta<select v-model="selection" required :disabled="loading||busy" @change="confirmed=false"><option disabled :value="0">Selecione uma consulta</option><option v-for="item in rows" :key="item.id" :value="item.id" :disabled="!item.ativo">{{ item.nome }}{{ item.ativo?'':' · Inativa' }}</option></select></label><p v-if="!loading&&!error&&!rows.length">Ainda não há consultas neste escritório. Configure uma consulta em Cadastros → Sindicatos.</p><section v-if="chosen" class="collection-summary"><h3>{{ chosen.nome }}</h3><p v-if="chosen.sindicato_nome">{{ chosen.sindicato_nome }}</p><dl><dt>CNPJ</dt><dd>{{ chosen.cnpj_filtro||'Sem filtro' }}</dd><dt>Categoria</dt><dd>{{ chosen.categoria||'Sem filtro' }}</dd><dt>UF</dt><dd>{{ chosen.uf||'Todas' }}</dd><dt>Título</dt><dd>{{ chosen.titulo||'Sem filtro' }}</dd><dt>Vigência</dt><dd>{{ chosen.vigencia||'Sem filtro' }}</dd><dt>Instrumentos</dt><dd>{{ chosen.tipos.join(', ') }}</dd></dl><p v-if="!eligible" role="alert">{{ issue }}</p></section><label class="confirmation-check"><input v-model="confirmed" type="checkbox" :disabled="busy||!eligible">Confirmo a coleta com os filtros desta consulta.</label><footer><button type="button" class="secondary" :disabled="busy" @click="close">Cancelar</button><button type="submit" class="primary" :disabled="busy||loading||!eligible||!confirmed">{{ busy?'Solicitando…':'Confirmar solicitação' }}</button></footer></form></AppDialog></template>
<style scoped>.collection-summary dl{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,2fr);gap:8px}.collection-summary dd{margin:0;overflow-wrap:anywhere}.collection-summary dt{font-weight:600}</style>
